$ErrorActionPreference='Stop';$dockerfile='backend/SanSo.Api.V6/Dockerfile';$text=Get-Content -LiteralPath $dockerfile -Raw -Encoding UTF8;$old="COPY --from=build /out .`nENV ASPNETCORE_URLS=http://+:8080";$new="COPY --from=build /out .`nRUN apt-get update && apt-get install -y --no-install-recommends curl && rm -rf /var/lib/apt/lists/*`nENV ASPNETCORE_URLS=http://+:8080";if(-not$text.Contains($old)){throw 'API_DOCKERFILE_HEALTH_ANCHOR_NOT_FOUND'};$text=$text.Replace($old,$new);[System.IO.File]::WriteAllText((Join-Path(Get-Location)$dockerfile),$text,[System.Text.UTF8Encoding]::new($false));foreach($path in @('docker-compose.yml','docker-compose.v14.yml')){$text=Get-Content -LiteralPath $path -Raw -Encoding UTF8;$old='wget -qO- http://127.0.0.1:8080/health >/dev/null || exit 1';$new='curl -fsS http://127.0.0.1:8080/health >/dev/null || exit 1';if(-not$text.Contains($old)){throw "COMPOSE_HEALTH_ANCHOR_NOT_FOUND:${path}"};$text=$text.Replace($old,$new);[System.IO.File]::WriteAllText((Join-Path(Get-Location)$path),$text,[System.Text.UTF8Encoding]::new($false))};'API_CONTAINER_HEALTHCHECK_FIXED_V2=3'
